function ContactForm() {
  const [values, setValues] = useState({ name: "", email: "", phone: "" });
  const [errors, setErrors] = useState({});
  const [status, setStatus] = useState("");

  const nameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const setField = (key) => (val) => {
    setValues((v) => ({ ...v, [key]: val }));
    if (errors[key]) {
      setErrors((e) => {
        const next = { ...e };
        delete next[key];
        return next;
      });
    }
  };

  function validate(v) {
    const e = {};
    if (!v.name.trim()) {
      e.name = "Enter your full name.";
    }
    if (!v.email.trim()) {
      e.email = "Enter your email address.";
    } else if (!EMAIL_RE.test(v.email.trim())) {
      e.email = "Enter a valid email like name@example.com.";
    }
    if (v.phone.trim() && !PHONE_RE.test(v.phone.trim())) {
      e.phone = "Enter a valid phone number, for example +1 555-123-4567.";
    }
    return e;
  }

  function handleSubmit(event) {
    event.preventDefault();
    const e = validate(values);
    setErrors(e);
    if (Object.keys(e).length > 0) {
      setStatus("");
      const order = ["name", "email", "phone"];
      const first = order.find((k) => e[k]);
      const refs = { name: nameRef, email: emailRef, phone: phoneRef };
      refs[first]?.current?.focus();
      return;
    }
    setStatus(`Thanks, ${values.name.trim()}. Your message has been sent. Our team will reply to ${values.email.trim()} shortly.`);
    setValues({ name: "", email: "", phone: "" });
  }

  return (
    <form className="card" noValidate onSubmit={handleSubmit} aria-labelledby="form-heading">
      <h2 id="form-heading" style={{marginTop: 0}}>Send us a message</h2>
      <p className="required-note">
        Fields marked with <span className="req-mark" aria-hidden="true">*</span>
        <span className="visually-hidden">an asterisk</span> are required.
      </p>

      <Field
        id="name"
        label="Full name"
        type="text"
        required
        autoComplete="name"
        value={values.name}
        onChange={setField("name")}
        error={errors.name}
        inputRef={nameRef}
      />

      <Field
        id="email"
        label="Email address"
        type="email"
        required
        autoComplete="email"
        value={values.email}
        onChange={setField("email")}
        error={errors.email}
        inputRef={emailRef}
      />

      <Field
        id="phone"
        label="Phone number"
        type="tel"
        required={false}
        autoComplete="tel"
        inputMode="tel"
        value={values.phone}
        onChange={setField("phone")}
        error={errors.phone}
        helpText="Include country code if outside the US, for example +1 555-123-4567. Digits, spaces, dashes, dots, and parentheses are allowed."
        inputRef={phoneRef}
      />

      <div className="actions">
        <button type="submit">Send message</button>
      </div>

      <div className="form-status" role="status" aria-live="polite">
        {status}
      </div>
    </form>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ContactForm />);
