const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Accept digits, spaces, dashes, parens, dots, optional leading +; require 7-15 digits.
const PHONE_RE = /^\+?[\d\s().-]{7,}$/;

function Field({ id, label, type, required, value, onChange, error, helpText, autoComplete, inputMode, placeholder, inputRef }) {
  const helpId = helpText ? `${id}-help` : null;
  const errorId = `${id}-error`;
  const describedBy = [helpId, error ? errorId : null].filter(Boolean).join(" ") || undefined;

  return (
