        <span className="visually-hidden">an asterisk</span> are required.
      </p>

      <Field
        id="name"
        label="Full name"
        type="text"
        required
        autoComplete="name"
        value={values.name}
        onChange={setField("name")}
        error={errors.name}
        inputRef={nameRef}
      />

      <Field
        id="email"
        label="Email address"
        type="email"
        required
        autoComplete="email"
        value={values.email}
        onChange={setField("email")}
        error={errors.email}
        inputRef={emailRef}
      />

      <Field
        id="phone"
        label="Phone number"
        type="tel"
        required={false}
        autoComplete="tel"
        inputMode="tel"
        value={values.phone}
        onChange={setField("phone")}
        error={errors.phone}
        helpText="Include country code if outside the US, for example +1 555-123-4567. Digits, spaces, dashes, dots, and parentheses are allowed."
        inputRef={phoneRef}
      />

      <div className="actions">
        <button type="submit">Send message</button>
      </div>

      <div className="form-status" role="status" aria-live="polite">
        {status}
      </div>
    </form>
  );
}

